(()=>{
'use strict';if(window.__gtavAdminOnboardingLoaded)return;window.__gtavAdminOnboardingLoaded=true;
const API='/api/onboarding-analytics',TOKEN_KEY='gtav-admin-token-v2';let tab,panel,statusNode;
const $=id=>document.getElementById(id);const fmt=n=>new Intl.NumberFormat().format(Number(n||0));
function headers(){return{'X-Admin-Token':sessionStorage.getItem(TOKEN_KEY)||'','Accept':'application/json'}}
async function req(){const r=await fetch(API,{cache:'no-store',headers:headers()});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||'request_failed');return d}
function rank(root,rows){root.replaceChildren();if(!rows.length){root.innerHTML='<div class="empty">No data yet.</div>';return}const max=Math.max(1,...rows.map(r=>Number(r.count||0)));rows.forEach(r=>{const item=document.createElement('div');item.className='survey-rank';const line=document.createElement('div');line.className='survey-rank-line';const label=document.createElement('span');label.textContent=r.label||'Unknown';const value=document.createElement('strong');value.textContent=fmt(r.count);line.append(label,value);const track=document.createElement('div');track.className='survey-track';const fill=document.createElement('i');fill.style.width=(Number(r.count||0)/max*100)+'%';track.append(fill);item.append(line,track);root.append(item)})}
async function load(){if(!sessionStorage.getItem(TOKEN_KEY)){statusNode.textContent='Unlock the dashboard first.';return}statusNode.textContent='Loading…';try{const d=await req(),s=d.summary||{};$('survey-total').textContent=fmt(s.total);$('survey-today').textContent=fmt(s.today);$('survey-ios').textContent=fmt(s.ios);$('survey-android').textContent=fmt(s.android);rank($('survey-sources'),d.sources||[]);rank($('survey-devices'),d.devices||[]);rank($('survey-models'),d.models||[]);statusNode.textContent='Synced.'}catch(e){statusNode.textContent=e.message==='unauthorized'?'Admin session is locked.':'Onboarding analytics unavailable.'}}
function activate(){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===tab));document.querySelectorAll('.panel').forEach(x=>x.classList.toggle('active',x===panel));load()}
function build(){const tabs=document.querySelector('.tabs'),anchor=document.querySelector('#panel-releases');if(!tabs||!anchor)return;tab=document.createElement('button');tab.className='tab';tab.type='button';tab.textContent='Onboarding';tab.addEventListener('click',activate);const notificationTab=[...tabs.querySelectorAll('.tab')].find(x=>x.textContent.trim()==='Notifications');notificationTab?tabs.insertBefore(tab,notificationTab):tabs.append(tab);panel=document.createElement('section');panel.className='panel';panel.id='panel-onboarding';panel.innerHTML=`<div class="survey-head"><div><h2>Onboarding insights</h2><p>Aggregate answers from the new-user form.</p></div><div><button class="mini" id="survey-refresh" type="button">Refresh</button> <span id="survey-status" class="form-status"></span></div></div><div class="survey-metrics"><div class="metric"><small>Total responses</small><strong id="survey-total">0</strong><span>Completed onboarding</span></div><div class="metric"><small>Today</small><strong id="survey-today">0</strong><span>New responses</span></div><div class="metric"><small>Selected iOS</small><strong id="survey-ios">0</strong><span>Play OS choice</span></div><div class="metric"><small>Selected Android</small><strong id="survey-android">0</strong><span>Play OS choice</span></div></div><div class="survey-grid"><section class="card"><div class="card-head"><div><h2>How users found the project</h2><small>YouTube, TikTok, Browser, Friends, Other</small></div></div><div id="survey-sources"></div></section><section class="card"><div class="card-head"><div><h2>Selected operating system</h2><small>Device choice from onboarding</small></div></div><div id="survey-devices"></div></section><section class="card survey-model-card"><div class="card-head"><div><h2>Selected iPhone models</h2><small>Model choice from onboarding</small></div></div><div id="survey-models"></div></section></div>`;anchor.after(panel);statusNode=$('survey-status');$('survey-refresh').addEventListener('click',load);const style=document.createElement('style');style.textContent='.survey-head{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;margin-bottom:14px}.survey-head h2{margin:0 0 4px;font-size:1.1rem}.survey-head p{margin:0;color:var(--muted,#888);font-size:.72rem}.survey-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:11px;margin-bottom:14px}.survey-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.survey-model-card{grid-column:1/-1}.survey-rank{margin:12px 0}.survey-rank-line{display:flex;justify-content:space-between;gap:12px;font-size:.73rem}.survey-track{height:7px;margin-top:6px;border-radius:999px;overflow:hidden;background:color-mix(in srgb,currentColor 8%,transparent)}.survey-track i{display:block;height:100%;border-radius:inherit;background:var(--site-accent,#e8b65e)}@media(max-width:860px){.survey-metrics,.survey-grid{grid-template-columns:1fr 1fr}}@media(max-width:560px){.survey-head{align-items:flex-start;flex-direction:column}.survey-metrics,.survey-grid{grid-template-columns:1fr 1fr}.survey-model-card{grid-column:1/-1}}';document.head.append(style)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',build);else build();
})();
